{
  "lines": [
    {
      "id": "story.world_months",
      "tiers": [
        {
          "id": "story.world_months:t1",
          "title": "Улитка открывает архив",
          "phrase": "В 2 разных календарных месяцах ты сохранил эпизоды. Улитка-архивариус завела вторую папку — дело набирает ход!",
          "imagePrompt": "A bespectacled snail opens a tiny filing drawer built into its spiral shell, placing a saved episode reel into the second of two folders. Its feelers lean eagerly toward the new folder while the first bulges with keepsakes.",
          "fishMarkup": "[warm]В 2 разных календарных месяцах ты сохранил эпизоды. Улитка-архивариус завела вторую папку — <emphasis>дело набирает ход!</emphasis>",
          "audioText": "В 2 разных календарных месяцах ты сохранил эпизоды. Улитка-архивариус завела вторую папку — дело набирает ход!"
        },
        {
          "id": "story.world_months:t2",
          "title": "Ракушка с читальным залом",
          "phrase": "Уже в 6 разных календарных месяцах ты сохранял эпизоды. У улитки-архивариуса теперь не ракушка, а филиал библиотеки.",
          "imagePrompt": "A bespectacled snail tends a growing library inside its spiral shell, with six open drawers holding episode reels. It balances on a sliding ladder to shelve a fresh reel, while a leaf-shaped bookmark pokes from an overstuffed folder.",
          "fishMarkup": "[confident]Уже в 6 разных календарных месяцах ты сохранял эпизоды. У улитки-архивариуса теперь не ракушка, а <emphasis>филиал библиотеки.</emphasis>",
          "audioText": "Уже в 6 разных календарных месяцах ты сохранял эпизоды. У улитки-архивариуса теперь не ракушка, а филиал библиотеки."
        },
        {
          "id": "story.world_months:t3",
          "title": "Календарь в очереди",
          "phrase": "Ты сохранил эпизоды в 12 разных календарных месяцах! Улитка-архивариус открыла приём: теперь календарь стоит к ней в очереди.",
          "imagePrompt": "A bespectacled snail runs a check-in counter beneath its enormous spiral-shell archive. A queue of walking blank calendar pads waits with episode reels; the snail calmly stamps a folder while the last calendar drags a folding stool.",
          "fishMarkup": "[triumphant]Ты сохранил эпизоды в 12 разных календарных месяцах! Улитка-архивариус открыла приём: [pause]<slow>теперь календарь стоит к ней в очереди.</slow>",
          "audioText": "Ты сохранил эпизоды в 12 разных календарных месяцах! Улитка-архивариус открыла приём: теперь календарь стоит к ней в очереди."
        }
      ]
    },
    {
      "id": "story.story_weeks",
      "tiers": [
        {
          "id": "story.story_weeks:t1",
          "title": "Хвост в первом ряду",
          "phrase": "Ты сохранил эпизоды в 4 разных неделях. Бобр-киномеханик включил проектор — даже хвост занял место в первом ряду.",
          "imagePrompt": "A beaver projectionist threads a film strip through a compact projector beside four saved episode reels. Its broad tail accidentally occupies the only audience chair, and it twists around to shoo its own tail away.",
          "fishMarkup": "[warm]Ты сохранил эпизоды в 4 разных неделях. Бобр-киномеханик включил проектор — <emphasis>даже хвост занял место в первом ряду.</emphasis>",
          "audioText": "Ты сохранил эпизоды в 4 разных неделях. Бобр-киномеханик включил проектор — даже хвост занял место в первом ряду."
        },
        {
          "id": "story.story_weeks:t2",
          "title": "Премьера на плотине",
          "phrase": "Эпизоды ты сохранял уже в 12 разных неделях. Бобр-киномеханик развернул экран на плотине: твоей истории тесно в будке.",
          "imagePrompt": "A beaver projectionist hauls a wide folded screen onto its wooden dam beside a tall rack of saved episode reels and a larger projector. Its tail pins down the screen's stand as curious fish gather at the waterline.",
          "fishMarkup": "[confident]Эпизоды ты сохранял уже в 12 разных неделях. Бобр-киномеханик развернул экран на плотине: <emphasis>твоей истории тесно в будке.</emphasis>",
          "audioText": "Эпизоды ты сохранял уже в 12 разных неделях. Бобр-киномеханик развернул экран на плотине: твоей истории тесно в будке."
        },
        {
          "id": "story.story_weeks:t3",
          "title": "Река требует продолжения",
          "phrase": "Ты сохранил эпизоды в 26 разных неделях — бобр-киномеханик открыл речной кинотеатр! Рыбы требуют продолжения — и водостойкий попкорн.",
          "imagePrompt": "A beaver projectionist operates a giant reel-powered projector atop its dam, turning a waterfall into a cinema screen. Fish queue below at a submerged popcorn hatch, each carrying a sealed snack jar, while the beaver's tail serves as the ticket ramp.",
          "fishMarkup": "[triumphant]Ты сохранил эпизоды в 26 разных неделях — бобр-киномеханик открыл речной кинотеатр! Рыбы требуют продолжения — [pause]<slow>и водостойкий попкорн.</slow>",
          "audioText": "Ты сохранил эпизоды в 26 разных неделях — бобр-киномеханик открыл речной кинотеатр! Рыбы требуют продолжения — и водостойкий попкорн."
        }
      ]
    }
  ]
}
